const sheets = $('Webhook').first().json.body.sheets;
const text = $json.output ?? $json.text ?? '';
let parsed;
try {
  parsed = JSON.parse(text);
  if (!Array.isArray(parsed)) throw new Error('not an array');
} catch (e) {
  // Fall back to an empty suggestion per sheet rather than losing the
  // whole batch to one malformed response -- a human still reviews every
  // row in the CSV either way.
  parsed = sheets.map((s) => ({
    sheet: s.sheet,
    suggested_system: '',
    reasoning: 'AI 응답을 JSON 배열로 파싱하지 못함: ' + text,
  }));
}
return [{ json: { suggestions: parsed } }];
